
// This is a service worker file for handling notifications.
// It's imported by the main service worker generated by next-pwa.

self.addEventListener('install', () => {
    self.skipWaiting();
    console.log('Dhuwa Notification Service Worker installing.');
});

self.addEventListener('activate', event => {
    event.waitUntil(self.clients.claim());
    console.log('Dhuwa Notification Service Worker activating.');
});


// Listener for scheduling notifications from the client app
self.addEventListener('message', (event) => {
    // Ensure we have the necessary APIs and a valid message type
    if (event.data?.type === 'SCHEDULE_MOMENT' && 'showTrigger' in self.Notification.prototype && self.registration) {
        const { momentId, userId, dateStr, plannedAtMs, label, habit, url } = event.data.payload;

        const nudgeAt = plannedAtMs - 5 * 60 * 1000;
        const checkAt = plannedAtMs + 5 * 60 * 1000;
        
        // Safety check: Don't schedule notifications in the past
        if (nudgeAt < Date.now() && checkAt < Date.now()) {
            return;
        }

        // Schedule "nudge" notification (5 minutes before)
        if (nudgeAt > Date.now()) {
            const nudgePromise = self.registration.showNotification("A Moment of Choice", {
                body: `Your planned smoke "${label}" is in 5 minutes.`,
                data: { url, userId, momentId, dateStr, kind: "nudge" },
                showTrigger: new self.TimestampTrigger(nudgeAt),
                tag: `moment:${momentId}:nudge`,
                renotify: true,
                icon: '/1080x1080.png',
            });
            event.waitUntil(nudgePromise);
        }

        // Schedule "check-in" notification (5 minutes after)
         if (checkAt > Date.now()) {
            const checkinPromise = self.registration.showNotification(`Checking In: ${label}`, {
                body: "The moment has passed. Did you end up smoking?",
                actions: [
                    { action: "log_yes", title: "Yes, I smoked" },
                    { action: "log_no", title: "No, I skipped it!" },
                ],
                data: { url, userId, momentId, dateStr, habit, kind: "checkin" },
                showTrigger: new self.TimestampTrigger(checkAt),
                tag: `moment:${momentId}:checkin`,
                renotify: true,
                requireInteraction: true,
                icon: '/1080x1080.png',
            });
            event.waitUntil(checkinPromise);
        }
    }
});


// Listener for when a user clicks on a notification action
self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    const { action } = event;
    const data = event.notification.data || {};
    const { url } = data;

    // If user just clicks the notification body (not a button), open the app
    if (!action) {
        event.waitUntil(clients.openWindow(url || '/'));
        return;
    }

    // Handle the "Yes" or "No" action
    if (action === 'log_yes' || action === 'log_no') {
        const smoked = action === 'log_yes';
        // The service worker will attempt to send this to the server.
        // If the user is offline, this fetch will fail. Robust queuing can be added later.
        const logPromise = fetch('/api/log-from-notification', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ ...data, smoked }),
        });
        event.waitUntil(logPromise);
    }
});
